package edu.pe.cibertec.saibm.inventario;
import static org.assertj.core.api.Assertions.assertThat; import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.json.JsonMapper; import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule; import java.time.*; import java.util.*; import java.util.concurrent.*; import java.util.concurrent.atomic.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.boot.autoconfigure.EnableAutoConfiguration; import org.springframework.boot.autoconfigure.flyway.FlywayAutoConfiguration; import org.springframework.boot.autoconfigure.jdbc.DataSourceAutoConfiguration; import org.springframework.boot.autoconfigure.orm.jpa.HibernateJpaAutoConfiguration; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.context.annotation.*; import org.springframework.amqp.rabbit.annotation.EnableRabbit; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.testcontainers.junit.jupiter.*; import org.testcontainers.rabbitmq.RabbitMQContainer; import edu.pe.cibertec.saibm.inventario.application.port.in.InventoryUseCase; import edu.pe.cibertec.saibm.inventario.application.port.out.InboxPort; import edu.pe.cibertec.saibm.inventario.infrastructure.messaging.*;
@SpringBootTest(properties={"eureka.client.enabled=false"},classes=RabbitRoundTripTest.Config.class) @Testcontainers class RabbitRoundTripTest { @Container static final RabbitMQContainer MQ=new RabbitMQContainer("rabbitmq:4.1.3-management-alpine"); @DynamicPropertySource static void rabbit(DynamicPropertyRegistry r){r.add("spring.rabbitmq.host",MQ::getHost);r.add("spring.rabbitmq.port",MQ::getAmqpPort);r.add("spring.rabbitmq.username",MQ::getAdminUsername);r.add("spring.rabbitmq.password",MQ::getAdminPassword);} @Autowired RabbitTemplate rabbit; @Autowired AtomicInteger calls; @Autowired CountDownLatch deliveries; @Autowired ObjectMapper mapper;
 @Test void duplicateRabbitEventIsConsumedOnce() throws Exception {var p=Map.<String,Object>of("bookId","book-1","quantity",1,"expiresAt","2030-01-01T00:00:00Z","operationKey","k1");var e=new EventEnvelope(UUID.randomUUID(),"InventoryHoldRequested.v1",1,Instant.now(),"c","x","test",p);rabbit.convertAndSend("saibm.inventory.v1","InventoryHoldRequested.v1",mapper.writeValueAsString(e));rabbit.convertAndSend("saibm.inventory.v1","InventoryHoldRequested.v1",mapper.writeValueAsString(e));assertThat(deliveries.await(10,TimeUnit.SECONDS)).isTrue();assertThat(calls).hasValue(1);}
 @Configuration @EnableAutoConfiguration(exclude={DataSourceAutoConfiguration.class,HibernateJpaAutoConfiguration.class,FlywayAutoConfiguration.class}) @EnableRabbit @Import(RabbitConfig.class) static class Config { @Bean ObjectMapper mapper(){return JsonMapper.builder().addModule(new JavaTimeModule()).build();} @Bean AtomicInteger calls(){return new AtomicInteger();} @Bean CountDownLatch deliveries(){return new CountDownLatch(2);} @Bean InboxPort inbox(CountDownLatch l){var ids=ConcurrentHashMap.<UUID>newKeySet();return (id,type)->{l.countDown();return ids.add(id);};} @Bean InventoryUseCase usecase(AtomicInteger c){return new InventoryUseCase(){public Outcome hold(String b,int q,Instant e,String k,String x){c.incrementAndGet();return null;}public Outcome commit(String b,String k,String x){return null;}public Outcome release(String b,String k,String x){return null;}};} @Bean InventoryMessageListener listener(InventoryUseCase u,InboxPort i,ObjectMapper m){return new InventoryMessageListener(u,i,m);}}
}
